def for_course(items):
    result = {}
    for item in items:
        learn, challenge, scenario, constraints, question = BRIEFS[item['key']]
        result[item['id']] = dict(learn=[learn], challenge=challenge, scenario=scenario,
                                  constraints=[constraints], question=question)
    return result
